mapper.select:
SELECT hypervisor_id, status, availability_zone,
       total_vcpu, reserved_vcpu, allocated_vcpu,
       total_memory_gb, reserved_memory_gb, allocated_memory_gb,
       total_gpu, reserved_gpu, allocated_gpu, resource_version
FROM hypervisor_resource
WHERE status = 'ACTIVE'
  AND available_vcpu >= #{vcpus}
  AND available_memory_gb >= #{memoryGb}
  AND available_gpu >= #{gpuCount}

  AND availability_zone = #{availabilityZone}

ORDER BY hypervisor_id
LIMIT #{limit}
